payload.text:
Agisci come un Senior React Developer.

Ho bisogno di implementare la sincronizzazione delle telemetrie e il grafico del **Delta (Gap Analysis)** nella mia dashboard `App.tsx`.
Voglio usare un approccio basato su "Resampling" (sincronizzazione su asse comune) per correggere i difetti dei dati GPS e ottenere un grafico delta preciso.

Esegui queste due operazioni:

### 1. AGGIORNA `utils/telemetryUtils.ts`
Sostituisci completamente il contenuto del file con questa logica di sincronizzazione e calcolo delta:

```typescript
// utils/telemetryUtils.ts

function interpolate(x: number, xPoints: number[], yPoints: number[]): number {
  if (xPoints.length === 0) return 0;
  if (x <= xPoints[0]) return yPoints[0];
  if (x >= xPoints[xPoints.length - 1]) return yPoints[yPoints.length - 1];
  let low = 0, high = xPoints.length - 1;
  while (low < high) {
    const mid = (low + high) >>> 1;
    if (xPoints[mid] < x) low = mid + 1;
    else high = mid;
  }
  const i = low - 1;
  const x0 = xPoints[i], x1 = xPoints[i + 1], y0 = yPoints[i], y1 = yPoints[i + 1];
  if (x1 === x0) return y0;
  return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
}

export const synchronizeTelemetry = (driversData: { [key: string]: any[] }, step: number = 5) => {
  const driverIds = Object.keys(driversData);
  if (driverIds.length === 0) return { axis: [], drivers: {} };

  // 1. Data Cleaning & Relative Time Calculation
  const processed: any = {};
  let minMaxDist = Infinity;

  driverIds.forEach(id => {
    const raw = driversData[id].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    if (raw.length < 2) return;

    const startT = new Date(raw[0].date).getTime();
    const startD = typeof raw[0].lap_distance === 'number' ? raw[0].lap_distance : 0;

    const dArr: number[] = [], tArr: number[] = [], rawObjs: any[] = [];
    let maxD = -1;

    raw.forEach(p => {
      const d = (typeof p.lap_distance === 'number' ? p.lap_distance : 0) - startD;
      // Monotonicity filter
      if (d > maxD && d >= 0) {
        maxD = d;
        dArr.push(d);
        tArr.push((new Date(p.date).getTime() - startT) / 1000);
        rawObjs.push(p);
      }
    });

    processed[id] = { d: dArr, t: tArr, v: rawObjs };
    if (maxD < minMaxDist) minMaxDist = maxD;
  });

  // 2. Common Axis
  const axis: number[] = [];
  for (let d = 0; d <= minMaxDist; d += step) axis.push(d);

  // 3. Interpolate All Fields
  const resultDrivers: any = {};
  driverIds.forEach(id => {
    const src = processed[id];
    if (!src) return;
    resultDrivers[id] = {
      relativeTime: axis.map(x => interpolate(x, src.d, src.t)),
      speed: axis.map(x => interpolate(x, src.d, src.v.map((p: any) => p.speed))),
      rpm: axis.map(x => interpolate(x, src.d, src.v.map((p: any) => p.rpm))),
      gear: axis.map(x => interpolate(x, src.d, src.v.map((p: any) => p.n_gear))),
      throttle: axis.map(x => interpolate(x, src.d, src.v.map((p: any) => p.throttle))),
      brake: axis.map(x => interpolate(x, src.d, src.v.map((p: any) => p.brake))),
      drs: axis.map(x => interpolate(x, src.d, src.v.map((p: any) => p.drs))),
    };
  });

  return { axis, drivers: resultDrivers };
};

export const calculateGapAnalysis = (syncedData: any, refId: string, compId: string, refTotal: number, compTotal: number) => {
  const ref = syncedData.drivers[refId];
  const comp = syncedData.drivers[compId];
  if (!ref || !comp) return [];

  // Raw Delta
  const raw = syncedData.axis.map((x: number, i: number) => comp.relativeTime[i] - ref.relativeTime[i]);

  // Drift Correction
  const trueGap = compTotal - refTotal;
  const graphGap = raw[raw.length - 1];
  const drift = trueGap - graphGap;
  const maxDist = syncedData.axis[syncedData.axis.length - 1];

  return raw.map((val: number, i: number) => ({
    x: syncedData.axis[i],
    y: val + (drift * (syncedData.axis[i] / maxDist))
  }));
};

```

2. AGGIORNA App.tsx
Modifica il file App.tsx per usare queste funzioni:

Aggiungi gli import: import { synchronizeTelemetry, calculateGapAnalysis } from './utils/telemetryUtils';

Dentro il componente App, usa useMemo per calcolare syncedTelemetry basato su telemetryData.

Usa useMemo per calcolare deltaSeries usando calculateGapAnalysis. Il reference deve essere il fastestLap.

Nel JSX, aggiungi il <TelemetrySingleChart> per il Delta (sopra o sotto quello della Speed).

Titolo: "Gap to [Reference Name]".

Formatter Asse Y: val => (val > 0 ? '+' : '') + val.toFixed(3) + 's'.

Genera il codice completo aggiornato per App.tsx che integra queste modifiche.
